+const vw = d => { const w = violinScale(d); return w < 0.1 ? 0 : Math.max(w, 1.8); };
+
 // --- Area generators ---
 const areaLeft = d3.area()
   .x0(0)
-  .x1(d => -violinScale(d[1]))
+  .x1(d => -vw(d[1]))
   .y(d => yScale(d[0]))
   .curve(d3.curveBasis);

 const areaRight = d3.area()
   .x0(0)
-  .x1(d => violinScale(d[1]))
+  .x1(d => vw(d[1]))
   .y(d => yScale(d[0]))
   .curve(d3.curveBasis);
